const defaults = {
  asofdate: null,
  securitytype: ['Kartik', 'Akira'],
  marketSector: ['Sandhya', 'Atharva'],
  numberofdays: 20,
  marketcaplowerlimit: 250000,
  sharefloat: 0.7,
  operator: 'OR',
  httpBodies: {
    market: {
      filters: {},
      groups: [
        { asOf: '2020-05-06', attribute_code: 'marketSector', value: { eq: 'Equity', type: 'text' }},
      ],
      limit: 100,
      logic: 'OR',
    },
    equity: {
      filters: { company_ids: [] },
      groups: [
        { asOf: '2020-05-06', attribute_code: 'securitytype', value: { eq: 'ETF', type: 'text' }},
      ],
      limit: 100,
      logic: 'AND',
    }
  }
};

function deepMerge(target, source) {
  for (const key in source) {
    if (
      source[key] && typeof source[key] === 'object' && !Array.isArray(source[key])
    ) {
      if (!target[key]) target[key] = {};
      deepMerge(target[key], source[key]);
    } else {
      target[key] = source[key];
    }
  }
  return target;
}

return items.map(item => {
  const inputBody = item.json.body || {};
  let output = JSON.parse(JSON.stringify(defaults)); // deep copy

  output = deepMerge(output, inputBody);

  if (!output.asofdate) {
    output.asofdate = new Date().toISOString().slice(0, 10);
  }

  item.json = output;
  return item;
});
